def intensite_restante(niveau_initial, vibrations):
    if vibrations == 0:
        return niveau_initial
    else:
        # La note perd 50% de son intensité à chaque vibration
        nouveau_niveau = niveau_initial / 2
        return intensite_restante(nouveau_niveau, vibrations - 1)

# Appel final pour l'exercice
print(intensite_restante(100, 3))
